// AppendLinks appends the links of v to out, in document order, and
// returns the extended slice.
func (v *AbstractDevice) AppendLinks(out []LinkRef) []LinkRef {
	if v == nil {
		return out
	}
	if x := v.AggregatedDeviceListLink; x != nil {
		out = append(out, LinkRef{Element: "AggregatedDeviceListLink", Type: "AggregatedDeviceListLink", Resource: "AggregatedDeviceList", Href: x.Href, All: x.All})
	}
	if x := v.AggregationPriorityLink; x != nil {
		out = append(out, LinkRef{Element: "AggregationPriorityLink", Type: "AggregationPriorityLink", Resource: "AggregationPriority", Href: x.Href})
	}
	if x := v.ConfigurationLink; x != nil {
		out = append(out, LinkRef{Element: "ConfigurationLink", Type: "ConfigurationLink", Resource: "Configuration", Href: x.Href})
	}
	if x := v.DERListLink; x != nil {
		out = append(out, LinkRef{Element: "DERListLink", Type: "DERListLink", Resource: "DERList", Href: x.Href, All: x.All})
	}
	if x := v.DeviceInformationLink; x != nil {
		out = append(out, LinkRef{Element: "DeviceInformationLink", Type: "DeviceInformationLink", Resource: "DeviceInformation", Href: x.Href})
	}
	if x := v.DeviceStatusLink; x != nil {
		out = append(out, LinkRef{Element: "DeviceStatusLink", Type: "DeviceStatusLink", Resource: "DeviceStatus", Href: x.Href})
	}
	if x := v.FileStatusLink; x != nil {
		out = append(out, LinkRef{Element: "FileStatusLink", Type: "FileStatusLink", Resource: "FileStatus", Href: x.Href})
	}
	if x := v.IPInterfaceListLink; x != nil {
		out = append(out, LinkRef{Element: "IPInterfaceListLink", Type: "IPInterfaceListLink", Resource: "IPInterfaceList", Href: x.Href, All: x.All})
	}
	if x := v.LoadShedAvailabilityListLink; x != nil {
		out = append(out, LinkRef{Element: "LoadShedAvailabilityListLink", Type: "LoadShedAvailabilityListLink", Resource: "LoadShedAvailabilityList", Href: x.Href, All: x.All})
	}
	if x := v.LogEventListLink; x != nil {
		out = append(out, LinkRef{Element: "LogEventListLink", Type: "LogEventListLink", Resource: "LogEventList", Href: x.Href, All: x.All})
	}
	if x := v.PowerStatusLink; x != nil {
		out = append(out, LinkRef{Element: "PowerStatusLink", Type: "PowerStatusLink", Resource: "PowerStatus", Href: x.Href})
	}
	return out
}

